console.log('Incoming payload:', JSON.stringify($json, null, 2));
const email = $json.resolvedEmail ? String($json.resolvedEmail).trim() : null;
const subject = $json.resolvedSubject || 'Your Adventure Itinerary - Voyage Genie';
let message = $json.resolvedMessage || 'No itinerary available to send.';

// Log the initial message
console.log('Step 1 - Initial message length:', message.length);
console.log('Step 1 - Initial message preview:', message.substring(0, 500));

// Step 1: Replace HTML tags with spaces to preserve content
message = message
  .replace(/<[^>]+>/g, ' ') // Replace HTML tags with a space
  .replace(/\s+/g, ' ') // Normalize multiple spaces to a single space
  .trim();

// Log after HTML tag removal
console.log('Step 2 - After HTML strip length:', message.length);
console.log('Step 2 - After HTML strip preview:', message.substring(0, 500));

// Step 2: Split into lines and clean up
let lines = message.split('\n')
  .map(line => line.trim()) // Trim each line
  .filter(line => line); // Remove empty lines

// Log after trimming lines
console.log('Step 3 - Lines after trim and filter:', lines);

// Step 3: Join lines back together with newlines
message = lines.length > 0 ? lines.join('\n') : message;

// Log after joining lines
console.log('Step 4 - After join length:', message.length);
console.log('Step 4 - After join preview:', message.substring(0, 500));

// Ensure message isn't empty after transformation
if (!message) {
  message = 'Transformed message was empty. Fallback: No itinerary available to send.';
  console.log('Message was empty after transformation, using fallback.');
}

// Validate email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!email || !emailRegex.test(email)) {
  console.log('Invalid email, using fallback:', email);
  return [{ json: { resolvedEmail: 'jtran112675@gmail.com', resolvedSubject: subject, resolvedMessage: message } }];
}

console.log('Sending email to:', email);
console.log('Final message length:', message.length);
console.log('Final message preview:', message.substring(0, 500));
return [{ json: { resolvedEmail: email, resolvedSubject: subject, resolvedMessage: message } }];

const message = $json.resolvedMessage || 'Fallback: No itinerary available to send.';
console.log('Final message to Gmail:', message);
return [{ json: { resolvedEmail: $json.resolvedEmail, resolvedSubject: $json.resolvedSubject, resolvedMessage: message } }];
